import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第七十四章 世间的事物是虚假不真实的吗？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/74第七十四章 世间的事物是虚假不真实的吗.md","filePath":"meditation/巴利文大藏经/74第七十四章 世间的事物是虚假不真实的吗.md"}'),o={name:"meditation/巴利文大藏经/74第七十四章 世间的事物是虚假不真实的吗.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第七十四章-世间的事物是虚假不真实的吗" tabindex="-1">第七十四章 世间的事物是虚假不真实的吗？ <a class="header-anchor" href="#第七十四章-世间的事物是虚假不真实的吗" aria-label="Permalink to &quot;第七十四章 世间的事物是虚假不真实的吗？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部12相应48经/顺世派经(因缘相应/因缘篇/修多罗)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园。有一天，顺世派婆罗门来到佛陀的住所，他与佛陀互相问候后，就在一旁坐下，顺世派婆罗门对佛陀说：“乔达摩，我有几个问题想要问你，你能为我解答吗？”</p><p>佛陀说：“婆罗门，你有什么问题，请说。”</p><p>顺世派婆罗门说：“乔达摩，世间一切的事物是真实存在的吗？”</p><p>佛陀说：“婆罗门，这是世间的一种见解，如来认为这是极端的见解。”</p><p>顺世派婆罗门说：“那，世间一切的事物是虚假不真实的吗？”</p><p>佛陀说：“婆罗门，这也是世间的一种见解，如来认为这也是极端的见解。”</p><p>顺世派婆罗门说：“那，世间一切的事物是密不可分的，是一个整体吗？”</p><p>佛陀说：“婆罗门，这样的见解，如来还是认为是一种极端的见解。”</p><p>顺世派婆罗门说：“那世间一切的事物是互不相干的，是各个不同的独立个体吗？”</p><p>佛陀说：“婆罗门，这种见解，如来还是认为是极端的见解。”</p><p>顺世派婆罗门有点不耐烦的说：“乔达摩，我已经把世间所有可能的见解都说了个遍，你都说这些见解是极端的见解，那你认为哪种见解是正确的呢？我现在实在是想不出还有什么见解可以用来描述世间的真相和规则了，你把你的见解说给我听听。”</p><p>佛陀说：“婆罗门，离开刚才你所说的见解，如来处于中道而说法：以「无明」为前提条件产生出「行」，以「行」为前提条件产生出「识」，以「识」为前提条件产生出「名色」，以「名色」为前提条件产生出「六处」，以「六处」为前提条件产生出「触」，以「触」为前提条件产生出「受」，以「受」为前提条件产生出「爱」，以「爱」为前提条件产生出「取」，以「取」为前提条件产生出「有」，以「有」为前提条件产生出「生」，这样有「生」就会产生出忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡。这就是世间人或众生痛苦和烦恼聚集、出现的过程，世间的人或众生按缘起法（缘起法解释，见第四十八章、第四十九章）的顺行就会继续的在生死轮回中煎熬沉沦，受尽折磨和痛苦。</p><p>「无明」完全褪去、消除、灭尽的时候，「行」就灭除了。「行」灭尽了，「识」就灭除了。「识」灭尽了，「名色」就灭除了。「名色」灭尽了，「六处」就灭除了。「六处」灭尽了，「触」就灭除了。「触」灭尽了，「受」就灭除了。「受」灭尽了，「爱」就灭除了。「爱」灭尽了，「取」就灭除了。「取」灭尽了，「有」就灭除了。「有」灭尽了，「生」就灭除了。「生」灭尽了，忧愁、悲伤、苦闷、忧虑、绝望、衰老、死亡就灭除了。这就是世间人或众生痛苦和烦恼灭除、灭尽的过程。世间的人或众生按缘起法（缘起法解释，见第四十八章、第四十九章）的逆行就能从生死轮回的烦恼和痛苦中解脱出来。”</p><p>佛陀说法后，顺世派婆罗门点点头，嗯了一声说到：“大德，您刚才说的很有道理，如果认为世间的事物是真实存在的，那么当世间的事物衰败、灭尽、消失的时候，就会认为这样的见解是不正确的。如果认为世间的事物是虚假不真实的，那么当世间的事物形成、出现、存在的时候，就会认为这样的见解是不正确的。如果认为世间的事物是密不可分的，是一个整体的，那么当世间的一些事物分割、分离之后，还是可以独立的存在，还是可以独自拥有具备分割、分离之前的性质、属性、功用，就会认为这样的见解是不正确的。如果认为世间的事物是互不相干的，是各个不同的独立个体，那么当世间的一些事物分割、分离之后，就会灭亡、消失，无法独立的存在，这些事物在分割、分离后就没有了分割、分离之前的性质、属性、功用，就会认为这样的见解是不正确的。我刚才对您说的这些见解都找得到反驳的论点。而刚才您所说的这个法理，却无法进行反驳，世间一切的事物确实是在一定的前提条件下形成、出现、存在的，也确实是在一定的前提条件下衰败、灭尽、消失的，是缘生缘灭的。我刚才说的那些见解其实都是世间事物出现、发展、变化、衰败、灭尽的不同阶段而已，在世间事物特定不同的阶段这些见解有其正确性，可是当这些阶段发生变化、互相变换的时候，这些见解就不一定正确了，应该说这些见解只是在特定的条件下才是正确的，看待问题的角度是片面性的，不是全面性的。大德，您刚才说的见解，不管放在世间事物的任何一个阶段都是正确的。我现在完全明白了，感谢您慈悲的为我讲解法理。</p><p>大德，请让我皈依您，请让我做您的在家修行弟子吧，我愿意受持您制定的戒律，我愿意按您所说的正法去修行。”</p><p>佛陀接受了顺世派婆罗门的皈依，顺世派婆罗门恭敬的顶礼佛陀，随喜赞叹佛陀说法的无量功德，并按着佛陀所说的法去修行。</p>',19)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
